package com.codequest;
public class View{
 public static String esc(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 public static String page(String title,String body){return page(title,body,"");}
 public static String page(String title,String body,String context){String root=context==null?"":context;return "<!doctype html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+esc(title)+" | CodeQuest</title>"+css()+"</head><body><nav><a class='brand' href='"+root+"/dashboard'>⚡ CodeQuest</a><div><a href='"+root+"/dashboard'>Dashboard</a><a href='"+root+"/missions'>Missions</a><a href='"+root+"/admin/login'>Admin</a><a href='"+root+"/logout'>Logout</a></div></nav><main><h1>"+esc(title)+"</h1>"+body+"</main><footer>CodeQuest · Learn by solving</footer></body></html>";}
 private static String css(){return "<style>*{box-sizing:border-box}body{margin:0;background:#0c1020;color:#edf0ff;font:16px Arial,sans-serif}nav{display:flex;justify-content:space-between;align-items:center;padding:18px 6%;background:#141a30;border-bottom:1px solid #2b3455;gap:18px;flex-wrap:wrap}nav a{color:#cbd3f5;text-decoration:none;margin-right:16px}.brand{font-weight:800;color:#9f8cff;font-size:22px}main{max-width:900px;margin:42px auto;padding:0 20px;min-height:65vh}h1{color:#fff}form,.card{background:#151c33;border:1px solid #303a60;border-radius:16px;padding:24px;margin:18px 0}label{display:block;margin:14px 0 7px;color:#b9c4ec}input,textarea,select{width:100%;padding:12px;border-radius:9px;border:1px solid #3d496e;background:#0d1327;color:white;margin-bottom:8px}button,.btn{background:#8b75ff;color:white;border:0;border-radius:9px;padding:12px 18px;cursor:pointer;font-weight:bold;text-decoration:none;display:inline-block;margin-top:12px}a{color:#b4a7ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.muted{color:#aab4d8}.error{color:#ff9696}.success{color:#8ff0bd}.pill{display:inline-block;padding:5px 10px;border-radius:20px;background:#29234f;color:#c7bbff;margin-right:6px}footer{text-align:center;color:#7984ab;padding:24px;border-top:1px solid #222b48}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #303a60;padding:10px}</style>"; }
}
